/*
 * PlotTest.kt
 * md (Android)
 *
 * The ```plot fence, against the oracle the site itself produced.
 *
 * WHERE THE EXPECTATIONS COME FROM
 * --------------------------------
 * `src/test/resources/plot-vectors.json` was generated by running
 * nettrash.me's own Rust — `render_plot_svg`, `nice_step`, `format_label` and
 * `preprocess_math_expr`, extracted verbatim from
 * `frontend/src/components/math.rs` — over 403 inputs: 81 tick spacings, 100
 * tick labels (each with the four Rust primitives that produced it), 162
 * evaluations, 38 malformed expressions and 22 whole figures. Every number in
 * it is recorded twice, once as JSON and once as the IEEE-754 bit pattern, so
 * "close enough" cannot creep in. The file is byte-identical to the copy in
 * `md.vscode/test/fixtures/`.
 *
 * It is an oracle, not a specification. Six of the behaviours it records are
 * bugs, and this suite asserts the **fixed** behaviour for those, in a table
 * that names each one and what the site did. Everything else must match the
 * vector exactly — there is no third category, and no row is skipped: a row
 * either matches its vector or appears in one of the correction tables below.
 *
 * This file mirrors `md.vscode/test/plot.test.ts` case for case, so a
 * divergence between the ports shows up as a failing assertion rather than as
 * two different figures. The one deliberate difference is the libm table: the
 * JVM's `Math` and Kotlin's `kotlin.math` are not V8's, and the rows where they
 * part company in the last bit are named below rather than tolerated wholesale.
 *
 * JSON is read by the hand-written parser at the foot of this file. The
 * unit-test classpath carries JUnit and nothing else — `org.json` is the
 * "not mocked" stub under `./gradlew test` — so a real parser is the only way
 * the corpus can be read at all, and it is thirty lines.
 */

package me.nettrash.md.markdown

import me.nettrash.md.book.EpubBook
import me.nettrash.md.book.EpubUnit
import me.nettrash.md.book.contentOpf
import me.nettrash.md.book.documentBody
import me.nettrash.md.book.toXhtml
import me.nettrash.md.book.xhtmlDocument
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.floor
import kotlin.math.log10

class PlotTest {

    // MARK: - The corpus

    private val vectors: JsonValue by lazy { loadVectors() }

    private fun loadVectors(): JsonValue {
        val stream = checkNotNull(javaClass.classLoader?.getResourceAsStream("plot-vectors.json")) {
            "missing plot-vectors.json"
        }
        return Json.parse(stream.bufferedReader(Charsets.UTF_8).use { it.readText() })
    }

    private fun rows(key: String): List<JsonValue> = vectors[key].array()

    /** `nan`, `inf` and `-inf` are JSON strings — JSON has no literal for them. */
    private fun real(value: JsonValue): Double = when {
        value.isString -> when (value.string()) {
            "nan" -> Double.NaN
            "inf" -> Double.POSITIVE_INFINITY
            "-inf" -> Double.NEGATIVE_INFINITY
            else -> throw AssertionError("not a number: ${value.string()}")
        }
        else -> value.number()
    }

    /** The big-endian IEEE-754 bit pattern, the way the vectors record a double. */
    private fun bits(value: Double): String = String.format("%016x", value.toRawBits())

    // MARK: - §1 nice_step — ported verbatim, so every row must match

    @Test fun niceStepReproducesAll81RecordedSpacingsBitForBit() {
        val recorded = rows("niceStep")
        assertEquals(81, recorded.size)
        for (row in recorded) {
            assertEquals(
                "niceStep(${row["input"]})",
                row["outputBits"].string(),
                bits(Plot.niceStep(real(row["input"]))),
            )
        }
    }

    /**
     * The decade is the mechanism, so the decade is what this pins.
     *
     * `9.999999999999999e-05` (bits 3f1a36e2eb1c432c) sits one ULP under 1e-4,
     * so the decade below it — the one [Plot.niceStep] must scale by — is 1e-5.
     * `floor(log10 …)` says −4 all the same, and the old code handed that
     * straight to a power function. `pow` is not correctly rounded and **is not
     * specified to be**, so `pow(10, n)` is a different double on different
     * *runtime versions*. Measured against the literal `1e<n>` over all 632
     * integer exponents in [-323, 308]: Node 20 disagrees at 68 of them on
     * arm64 and 69 on x86-64, Node 22 at 68, Node 24 at 2, Node 26 at none, and
     * OpenJDK 21 — this port's runtime — at 64, `StrictMath.pow` included. Not
     * a CPU difference: Node 20 is wrong on both architectures and Node 26 is
     * right on both. A wrong decade picks a different rung of the 1/2/5/10
     * ladder — a different step, a different number of ticks, different labels,
     * different bytes.
     *
     * This is a real failure, not a thought experiment: md.vscode's CI runs
     * Node 20 and is red on the pushed v1.2.0 (fd71a4e) with three failures in
     * `test/plot.test.ts`, `tiny_range` among them and an `xLabels` nine long
     * where this Mac — Node 26 — produces eight. Same source, same input, two
     * engine versions.
     *
     * The decade must therefore equal the **decimal literal**, whose parse is
     * specified to be correctly rounded in every language this renderer is
     * ported to. **`pow(10, e)` must never come back** — not in
     * `Plot.decadeOf`, not in `powerOfTen`, not anywhere the geometry can see
     * it.
     *
     * **What this pins, and what it does not.** It pins the *contract*: the
     * decade of the witness is the double that `"1e-5"` parses to, bit for bit,
     * and never 1e-4. It does not pin the *mechanism*. A `powerOfTen` rebuilt
     * on `Math.pow` fails here only because −5 happens to be one of OpenJDK
     * 21's 64 wrong exponents; on a runtime whose `pow` agreed with the literal
     * there — Darwin libm's is correct for all 632 — this assertion would pass
     * with `pow` in place and tell you nothing. The family's mechanism guard is
     * md.vscode's `test/plot.test.ts`, "gets the boundary decade right without
     * Math.pow, and survives a wrong log10": it replaces `Math.pow` with a
     * function that **throws**, so any reintroduction fails on every platform,
     * and it perturbs `log10` by ±1 decade while still demanding all 81 oracle
     * rows. Its CI runs Node 20, an affected engine. If you touch the decade
     * path here, run that one too.
     */
    @Test fun theDecadeOfABoundaryInputIsTheDecimalLiteralNotAPow() {
        val rough = java.lang.Double.longBitsToDouble(0x3f1a36e2eb1c432cL)
        assertEquals("the recorded witness", 9.999999999999999e-05, rough, 0.0)
        assertTrue("one ULP under 1e-4", rough < 1e-4)

        // What log10 on its own claims — an approximation, and here a wrong one.
        assertEquals("floor(log10) alone", -4.0, floor(log10(rough)), 0.0)

        // What the decade must be: the literal, bit for bit, however it is spelt.
        assertEquals("decadeOf", bits("1e-5".toDouble()), bits(Plot.decadeOf(rough)))
        assertEquals("the literal is the double", bits(1e-5), bits(Plot.decadeOf(rough)))

        // And the answer the unpinned code gave, which is what must not return.
        assertFalse("decade must not be 1e-4", Plot.decadeOf(rough) == 1e-4)
    }

    /**
     * The same pin across the whole exponent range the renderer can reach, on
     * both sides of every boundary: a power of ten is its own decade, and the
     * double just below it belongs to the decade beneath. 601 exponents,
     * [-300, 300], two inputs each.
     *
     * Expectations are spelt as parsed literals rather than computed, so the
     * test cannot agree with the code by sharing its mistake. It is still a
     * contract test rather than a mechanism test: it would catch a `Math.pow`
     * decade on *this* runtime — OpenJDK 21 disagrees with the literal at 62 of
     * these 601 exponents — but it would pass unchanged on a runtime whose
     * `pow` is correctly rounded. See the note on the previous test for the
     * guard that bites everywhere.
     */
    @Test fun everyDecadeBoundaryResolvesToTheLiteralOnBothSides() {
        for (exponent in -300..300) {
            val literal = "1e$exponent".toDouble()
            assertEquals("decadeOf(1e$exponent)", bits(literal), bits(Plot.decadeOf(literal)))
            assertEquals(
                "decadeOf(nextDown(1e$exponent))",
                bits("1e${exponent - 1}".toDouble()),
                bits(Plot.decadeOf(Math.nextDown(literal))),
            )
        }
    }

    /** The pin must be inert for the inputs `niceStep` cannot scale at all. */
    @Test fun theDecadePinLeavesDegenerateInputsAlone() {
        assertEquals("zero", bits(0.0), bits(Plot.decadeOf(0.0)))
        assertTrue("negative", Plot.decadeOf(-1.0).isNaN())
        assertTrue("nan", Plot.decadeOf(Double.NaN).isNaN())
        assertEquals("inf", bits(Double.POSITIVE_INFINITY), bits(Plot.decadeOf(Double.POSITIVE_INFINITY)))
        assertTrue("-inf", Plot.decadeOf(Double.NEGATIVE_INFINITY).isNaN())
    }

    @Test fun niceStepTakesEachOfTheFourBranches() {
        // norm <= 1.5, <= 3, <= 7, else — the `10 * mag` branch is the one a
        // careless port drops, and it is what draws [-32, 32] with a step of 10.
        assertEquals(1.0, Plot.niceStep(8.0), 0.0)
        assertEquals(2.0, Plot.niceStep(20.0), 0.0)
        assertEquals(5.0, Plot.niceStep(50.0), 0.0)
        assertEquals(10.0, Plot.niceStep(64.0), 0.0)
    }

    // MARK: - §2 format_label — ported with two corrections

    /**
     * The nine labels the site prints wrong, and what this renderer prints
     * instead.
     *
     * All nine are the same defect: `format_label`'s integer branch prints
     * `val as i64`, which **truncates**, so a tick that arrives one ULP below a
     * whole number loses a whole unit. SPEC §1.4 replaces the truncation with a
     * round, which is what `round()` in the same condition already implied.
     */
    private data class LabelFix(val input: Double, val site: String, val ours: String)

    private val correctedLabels = listOf(
        LabelFix(0.9999999999, "0", "1"),
        LabelFix(-0.9999999999, "0", "-1"),
        LabelFix(2.9999999996, "2", "3"),
        LabelFix(-2.9999999996, "-2", "-3"),
        LabelFix(999.9999999999, "999", "1000"),
        LabelFix(-999.9999999999, "-999", "-1000"),
        LabelFix(123.99999999995, "123", "124"),
        LabelFix(-123.99999999995, "-123", "-124"),
        LabelFix(999.9999999999999, "999", "1000"),
    )

    private fun correctedLabel(input: JsonValue): LabelFix? {
        if (input.isString) return null
        for (row in correctedLabels) if (row.input == input.number()) return row
        return null
    }

    @Test fun formatLabelReproducesAll100RecordedLabelsButForTheNineTheSiteTruncates() {
        val recorded = rows("formatLabel")
        assertEquals(100, recorded.size)
        var corrected = 0
        for (row in recorded) {
            val fix = correctedLabel(row["input"])
            val got = Plot.formatLabel(real(row["input"]))
            if (fix == null) {
                assertEquals("formatLabel(${row["input"]})", row["output"].string(), got)
            } else {
                assertEquals(
                    "the vector still records the site's ${row["input"]}",
                    fix.site,
                    row["output"].string(),
                )
                assertEquals("formatLabel(${row["input"]})", fix.ours, got)
                corrected++
            }
        }
        // Every row of the correction table was reached — a table entry that no
        // vector exercises is a claim about nothing.
        assertEquals(correctedLabels.size, corrected)
    }

    @Test fun formatLabelWritesRustsExponentialNotThePlatforms() {
        // THE cross-platform hazard, pinned on all 100 values: `1.0e3` and not
        // `1.0e+3` (JavaScript), `1.0e+03` (C, Java) or `1.0E3`; and ties to
        // even on the exact binary value, not the half-up rounding
        // `String.format` performs.
        for (row in rows("formatLabel")) {
            assertEquals(
                "{:.1e} of ${row["input"]}",
                row["rustPrimitives"]["fmt_1e"].string(),
                Plot.formatExponential(real(row["input"]), 1),
            )
        }
        // What the platform would have said.
        assertEquals("1.3e+03", String.format("%.1e", 1250.0))
        assertEquals("1.2e3", Plot.formatExponential(1250.0, 1)) // 1.25 → ties to even
        assertEquals("1.4e3", Plot.formatExponential(1350.0, 1)) // 1.35 → ties to even, upward
        assertEquals("1.3e-2", Plot.formatExponential(0.0125, 1)) // not a tie: the double is above it
        assertEquals("4.9e-324", Plot.formatExponential(4.9E-324, 1)) // the smallest subnormal
    }

    @Test fun formatLabelWritesRustsFixedFormNotStringFormat() {
        for (row in rows("formatLabel")) {
            // Past 25 significant digits `{:.2}` prints the double's whole exact
            // expansion (1e300 is 301 digits of it). `format_label` sends
            // everything from 1000 up to the exponential branch, so the fixed
            // formatter is never asked for one, and it stops at the digits it
            // can decide a rounding on.
            val expected = row["rustPrimitives"]["fmt_2f"].string()
            if (expected.length > 30) continue
            assertEquals("{:.2} of ${row["input"]}", expected, Plot.formatFixed(real(row["input"]), 2))
        }
        // What the platform would have said.
        assertEquals("0.13", String.format("%.2f", 0.125))
        assertEquals("0.12", Plot.formatFixed(0.125, 2)) // an exact tie, rounded to even
        assertEquals("8.12", Plot.formatFixed(8.125, 2))
        assertEquals("2.67", Plot.formatFixed(2.675, 2)) // the double is below the tie
        assertEquals("1000.00", Plot.formatFixed(999.999, 2)) // the carry runs off the fraction
        assertEquals("-0.00", Plot.formatFixed(-0.0, 2)) // Rust keeps the sign
    }

    // MARK: - §3 The expression language

    /**
     * The evaluations where this renderer deliberately answers differently.
     *
     * Four of the five families are SPEC §1.3's corrections; the fifth is the
     * `math::` prefix, which is not a language feature at all but the site's own
     * preprocessor showing through — it rewrites every roster name to `math::…`
     * before handing the text to evalexpr, so `math::sin(x)` happens to work
     * there. It is not in the roster, so it is a parse error here.
     */
    private data class EvalFix(val expr: String, val x: Double?, val value: Double, val why: String)

    private val correctedEval = listOf(
        // 1. floor / ceil / round draw. The site registers them bare and then
        //    asks evalexpr for `math::floor`, which is unbound, so all 1001
        //    samples fail and `broken_floor_no_curve.svg` has no polyline at all.
        EvalFix("floor(x)", 2.7, 2.0, "floor works"),
        EvalFix("floor(x)", -2.5, -3.0, "floor works"),
        EvalFix("ceil(x)", 2.1, 3.0, "ceil works"),
        EvalFix("ceil(x)", -2.5, -2.0, "ceil works"),
        EvalFix("round(x)", 2.5, 3.0, "round works, ties away from zero"),
        EvalFix("round(x)", -2.5, -3.0, "round works, ties away from zero"),
        EvalFix("round(x)", 0.5, 1.0, "round works, ties away from zero"),
        // 2. Comparisons and the Boolean operators are numbers, so they compose.
        EvalFix("x==1", 1.0, 1.0, "comparisons yield 1.0 / 0.0"),
        EvalFix("x!=1", 1.0, 0.0, "comparisons yield 1.0 / 0.0"),
        EvalFix("x<1", 0.0, 1.0, "comparisons yield 1.0 / 0.0"),
        EvalFix("x<=1", 1.0, 1.0, "comparisons yield 1.0 / 0.0"),
        EvalFix("x>1", 2.0, 1.0, "comparisons yield 1.0 / 0.0"),
        EvalFix("x>=1", 1.0, 1.0, "comparisons yield 1.0 / 0.0"),
        EvalFix("(x>0)*2", 1.0, 2.0, "a comparison multiplies"),
        EvalFix("!x", 1.0, 0.0, "negation is numeric"),
        EvalFix("1&&1", null, 1.0, "a number is a truth value"),
        EvalFix("1<2<3", null, 1.0, "comparisons chain left-associatively"),
        // 3. `^` is right-associative.
        EvalFix("2^3^2", null, 512.0, "2^(3^2), not (2^3)^2"),
        // 4. Everything is a double.
        EvalFix("5/2", null, 2.5, "no integer division"),
        EvalFix("-7/2", null, -3.5, "no integer division"),
        EvalFix("7/2", null, 3.5, "no integer division"),
        EvalFix("2+3*4-5/2", null, 11.5, "no integer division"),
        EvalFix("1/0", null, Double.POSITIVE_INFINITY, "division by zero is ±∞, not an error"),
        EvalFix("0/0", null, Double.NaN, "0/0 is NaN, not an error"),
        EvalFix("1%0", null, Double.NaN, "x%0 is NaN, not an error"),
    )

    /**
     * Expressions this language does not have.
     *
     * Every one of them is a **parse error** here, which is the point: on the
     * site most of these parse and then die silently at evaluation time, which
     * is why a typo currently looks like an empty chart rather than a message.
     */
    private val notInTheLanguage = listOf(
        // Not in the roster. evalexpr carries them; the four ports share a roster.
        "min(x,0)", "max(x,0)", "if(x>0,1,-1)", "log(8,2)", "typeof(x)",
        // The site's preprocessor showing through.
        "math::floor(x)", "math::sin(x)", "math::math::sin(x)", "math::log(8,2)",
        // Unknown names, and names that are nearly right.
        "mysin(x)", "x_sin(x)", "SIN(x)", "sinx", "foo(x)", "y", "X",
        "true&&false", "true||false", "!true",
        // Wrong arity — an error, not a silently empty chart.
        "sqrt(1,2)", "hypot(3)", "atan2(1)", "sin()",
        // Types and syntax the language has no use for.
        "\"abc\"", "(1,2)", "x=1", "0x10",
    )

    /**
     * Rows where the JVM's libm and Rust's libm disagree in the last bit.
     *
     * Six of 162, every one within one ULP, and every one a function neither
     * runtime rounds correctly. `Math.exp` and `Math.cosh` are the JVM's own
     * (both are specified only to within 1 ulp, and OpenJDK 21 on aarch64 lands
     * one ulp high on `exp(1)`); `asinh` and `atanh` are Kotlin's own
     * compositions of `ln` and `sqrt`; `asin` and `acos` are shared with the
     * TypeScript reference, which names the same two.
     *
     * Nothing can be done about it and nothing needs to be: one ULP is 10⁻¹⁶ of
     * a pixel coordinate, and the golden figure — 2002 coordinates, `exp` and
     * `sin` throughout — comes out byte-identical to the reference's anyway.
     * They are named rather than tolerated wholesale, so a *real* divergence in
     * any other function still fails.
     */
    private val libmUlp = listOf(
        "atanh(x)" to 0.5,
        "asin(x)" to 0.5,
        "acos(x)" to 0.5,
        "asinh(x)" to 1.0,
        "cosh(x)" to 1.0,
        "exp(x)" to 1.0,
    )

    private fun corrected(expr: String, x: Double): EvalFix? {
        for (row in correctedEval) {
            if (row.expr != expr) continue
            if (row.x != null && row.x != x) continue
            return row
        }
        return null
    }

    private fun isLibmRow(expr: String, x: Double): Boolean {
        for (row in libmUlp) if (row.first == expr && row.second == x) return true
        return false
    }

    private fun value(expr: String, x: Double): Double =
        Plot.evaluate(Plot.parseExpression(expr, "x"), "x", x)

    @Test fun theExpressionLanguageAccountsForAll162RecordedEvaluations() {
        val recorded = rows("eval")
        assertEquals(162, recorded.size)
        val seenCorrections = HashSet<String>()
        val seenAbsences = HashSet<String>()
        val failures = ArrayList<String>()

        for (row in recorded) {
            val expr = row["expr"].string()
            val x = real(row["x"])
            val label = "$expr at x=$x"

            val fix = corrected(expr, x)
            if (fix != null) {
                seenCorrections.add(expr)
                val got = value(expr, x)
                val ok = if (fix.value.isNaN()) got.isNaN() else got == fix.value
                if (!ok) failures.add("$label — ${fix.why}: got $got, wanted ${fix.value}")
                continue
            }

            if (notInTheLanguage.contains(expr)) {
                seenAbsences.add(expr)
                val threw = try {
                    value(expr, x)
                    false
                } catch (error: Plot.PlotError) {
                    assertNotNull(error.message)
                    true
                }
                if (!threw) failures.add("$label should have been a PlotError")
                continue
            }

            val want = real(row["result"])
            val got = value(expr, x)
            if (isLibmRow(expr, x)) {
                // Same value, possibly not the same last bit.
                if (!(Math.abs(got - want) / Math.abs(want) < 1e-15)) {
                    failures.add("$label — libm row is more than one ULP out: $got vs $want")
                }
                continue
            }
            if (want.isNaN()) {
                // NaN and not its payload: a runtime's libm may return a quiet
                // NaN spelt 7ffc000000000000 where Rust's returns
                // 7ff8000000000000, and no program can tell the difference.
                if (!got.isNaN()) failures.add("$label: got $got, wanted NaN")
                continue
            }
            if (bits(got) != row["resultBits"].string()) {
                failures.add("$label: got ${bits(got)} ($got), wanted ${row["resultBits"].string()} ($want)")
            }
        }

        assertTrue(failures.joinToString("\n"), failures.isEmpty())
        // Both tables are fully exercised by the corpus.
        assertEquals(correctedEval.map { it.expr }.toSet().size, seenCorrections.size)
        assertEquals(notInTheLanguage.size, seenAbsences.size)
    }

    @Test fun theExpressionLanguageRejectsEveryOneOfThe38MalformedExpressions() {
        val recorded = rows("parseErrors")
        assertEquals(38, recorded.size)
        for (row in recorded) {
            val expr = row["expr"].string()
            // Two of the site's failures are not failures here, and both are in
            // the grammar on purpose: `floor(x)` is correction 1, and `x ++ 2`
            // is `x + (+2)` — unary plus is a prefix operator in SPEC §1.3's
            // table.
            if (expr == "floor(x)" || expr == "x ++ 2") continue
            assertThrowsPlotError(expr) { value(expr, 1.0) }
        }
    }

    @Test fun theExpressionLanguageSaysWhatIsWrongInTheWordsSpec17Uses() {
        assertMessage("unknown function 'sinc'") { value("sinc(x)", 1.0) }
        assertMessage("expected ')'") { value("sin(x", 1.0) }
        assertMessage("sqrt takes 1 argument, not 2") { value("sqrt(1,2)", 1.0) }
        assertMessage("unknown name 'y'") { value("y", 1.0) }
    }

    @Test fun theExpressionLanguageBindsUnaryMinusLooserThanPowerAndPowerToTheRight() {
        assertEquals(512.0, value("2^3^2", 0.0), 0.0)
        assertEquals(512.0, value("2^(3^2)", 0.0), 0.0)
        assertEquals(64.0, value("(2^3)^2", 0.0), 0.0)
        assertEquals(-9.0, value("-x^2", 3.0), 0.0)
        assertEquals(9.0, value("(-x)^2", 3.0), 0.0)
        assertEquals(-4.0, value("-2^2", 0.0), 0.0)
        assertEquals(0.5, value("2^-1", 0.0), 0.0)
        assertEquals(-3.0, value("-x", 3.0), 0.0)
        assertEquals(3.0, value("--x", 3.0), 0.0)
    }

    /**
     * The five arguments where `Math.pow` is not IEEE 754's `pow`.
     *
     * C99 §F.9.4.4 and IEEE 754-2008 both say `pow(+1, y)` is 1 for **any** y —
     * ±∞ and NaN included — and that `pow(-1, ±∞)` is 1. Swift and Rust do that
     * (both are C's `pow` underneath); Java and JavaScript answer NaN to all
     * five, Java by an explicit clause in `Math.pow`'s contract ("if the
     * absolute value of the first argument equals 1 and the second argument is
     * infinite, then the result is NaN"). SPEC §1.3 makes every value here an
     * IEEE-754 double, so the two ports that agree with IEEE are the right ones
     * and this one is corrected to match. `Plot.powIEEE` is what does it, and
     * both spellings — the `^` operator and the `pow(a,b)` function — go
     * through it.
     *
     * `plot-vectors.json` has no row for any of the five, so this is not a
     * correction *against* the oracle; it is a case the oracle never reached.
     */
    @Test fun powIsOneForEveryExponentOfPositiveOneAndForInfinitePowersOfMinusOne() {
        val inf = Double.POSITIVE_INFINITY
        // pow(1, NaN) — the only NaN argument in all of arithmetic that is not
        // contagious.
        assertEquals(1.0, value("pow(1,x)", Double.NaN), 0.0)
        assertEquals(1.0, value("1^x", Double.NaN), 0.0)
        // pow(1, +inf)
        assertEquals(1.0, value("pow(1,x)", inf), 0.0)
        assertEquals(1.0, value("1^x", inf), 0.0)
        // pow(1, -inf)
        assertEquals(1.0, value("pow(1,x)", -inf), 0.0)
        assertEquals(1.0, value("1^x", -inf), 0.0)
        // pow(-1, +inf)
        assertEquals(1.0, value("pow(-1,x)", inf), 0.0)
        assertEquals(1.0, value("(-1)^x", inf), 0.0)
        // pow(-1, -inf)
        assertEquals(1.0, value("pow(-1,x)", -inf), 0.0)
        assertEquals(1.0, value("(-1)^x", -inf), 0.0)
        // Reached through an expression rather than a literal, because that is
        // how a curve actually walks into it: 1^(1/x) at x = 0.
        assertEquals(1.0, value("1^(1/x)", 0.0), 0.0)

        // And nothing else moves. Every neighbouring special case keeps IEEE's
        // own answer, which for these Java already gives.
        assertTrue(value("pow(x,x)", Double.NaN).isNaN()) // NaN^NaN is NaN
        assertEquals(inf, value("(-1.0000001)^x", inf), 0.0) // |base| > 1 → +∞
        assertEquals(0.0, value("(-1.0000001)^x", -inf), 0.0)
        assertTrue(value("pow(-1,x)", Double.NaN).isNaN()) // (-1)^NaN stays NaN
        assertEquals(1.0, value("pow(x,0)", Double.NaN), 0.0) // NaN^0 is 1, as Java already has it
        assertEquals(1.0, value("0^0", 0.0), 0.0)
        assertEquals(1024.0, value("2^10", 0.0), 0.0)
        assertTrue(value("pow(x,0.5)", -8.0).isNaN())
    }

    @Test fun theExpressionLanguageKnowsPiAndENothingElseWithoutParentheses() {
        assertEquals(Math.PI, value("pi", 0.0), 0.0)
        assertEquals(Math.E, value("e", 0.0), 0.0)
        assertEquals(7.3890560989306495, value("e^2", 0.0), 0.0)
        assertMessage("sin is a function") { value("sin", 0.0) }
    }

    // MARK: - §4 The four corrected behaviours, as figures

    /** Everything a rendered figure can be asked about without an XML parser. */
    private class Facts(
        val lines: Int,
        val texts: Int,
        val polylines: Int,
        val first: String?,
        val last: String?,
        val xLabels: List<String>,
        val yLabels: List<String>,
    )

    private fun facts(svg: String): Facts {
        val runs = allGroups(svg, "<polyline points=\"", "\"")
        val lastRun = runs.lastOrNull()?.split(" ")
        return Facts(
            lines = countOf(svg, "<line "),
            texts = countOf(svg, "<text "),
            polylines = runs.size,
            first = runs.firstOrNull()?.split(" ")?.firstOrNull(),
            last = lastRun?.lastOrNull(),
            xLabels = allGroups(svg, "text-anchor=\"middle\">", "</text>"),
            yLabels = allGroups(svg, "dominant-baseline=\"middle\">", "</text>"),
        )
    }

    private fun figure(source: String): Facts = facts(Plot.plotSVG(source))

    @Test fun correction1FloorCeilAndRoundDrawACurveWhereTheSiteDrawsNothing() {
        // `broken_floor_no_curve.svg` has 0 polylines. Here the staircase is one
        // run: floor(x) stays inside [-2, 2] for x in [-2, 3), and every step
        // lands inside the window, so nothing breaks it.
        val floor = figure("x: -10..10\ny: -2..2\nfloor(x)")
        assertEquals(1, floor.polylines)
        assertEquals("248.00,360.00", floor.first) // x = -2, y = -2: the bottom left
        assertEquals("377.48,40.00", floor.last) // x = 2.98, y = 2: the top of the last step
        assertTrue(figure("x: -10..10\ny: -2..2\nceil(x)").polylines > 0)
        assertTrue(figure("x: -10..10\ny: -2..2\nround(x)").polylines > 0)
    }

    @Test fun correction2AComparisonIsANumberSoTheHalfDomainIdiomDraws() {
        // `boolean_no_curve.svg` has 0 polylines for `x>0`.
        val step = figure("x: -10..10\ny: -2..2\nx>0")
        assertEquals(1, step.polylines)
        assertEquals("40.00,200.00", step.first) // 0 at the far left
        assertEquals("560.00,120.00", step.last) // 1 at the far right

        // The spec's own idiom. It draws exactly the half-domain it names: NaN
        // times zero is still NaN, so the left half stays empty and the curve
        // begins at the origin.
        val half = figure("x: -4..4\ny: -1..3\n(x>0)*sqrt(x)")
        assertEquals(1, half.polylines)
        assertEquals("300.00,280.00", half.first) // x = 0, y = 0
        assertEquals("560.00,120.00", half.last) // x = 4, y = 2

        // And where the guard has a finite value on both sides it is a
        // full-width curve with a kink — a rectifier, drawn from edge to edge.
        val relu = figure("x: -4..4\ny: -1..3\n(x>0)*x")
        assertEquals(1, relu.polylines)
        assertEquals("40.00,280.00", relu.first)
        // …until it climbs out of the window at y = 3, which is where the run ends.
        assertEquals("495.00,40.00", relu.last)
    }

    @Test fun correction3PowerIs512InAFigureNot64() {
        // A constant series is a flat line, so its height *is* the value: with
        // y: 0..1024 the line at 512 lands exactly halfway.
        val chart = figure("x: -1..1\ny: 0..1024\n2^3^2")
        assertEquals("40.00,200.00", chart.first)
        assertEquals("560.00,200.00", chart.last)
    }

    @Test fun correction4FiveOverTwoIsTwoPointFiveAndTheSiteDrawsItAtTwo() {
        // `int_division_trunc.svg` puts the line at y = 232, which is sy(2).
        val chart = figure("x: -1..1\ny: 0..5\n5/2")
        assertEquals("40.00,200.00", chart.first) // sy(2.5)
        assertEquals("560.00,200.00", chart.last)
    }

    @Test fun axisCorrectionLabelsATickAtMinusFourWhereTheSiteTruncatesToMinusThree() {
        // `tick_label_truncation.svg`, both axes [-5, -3]: the site's sixth
        // label reads "-3", out of order, in the middle of the axis.
        val chart = figure("x: -5..-3\ny: -5..-3\nx")
        assertEquals("-4", chart.xLabels[5])
        assertEquals("-4", chart.yLabels[5])
        assertEquals(
            listOf("-5", "-4.80", "-4.60", "-4.40", "-4.20", "-4", "-3.80", "-3.60", "-3.40", "-3.20", "-3"),
            chart.xLabels,
        )
    }

    @Test fun axisCorrectionLabelsTheTickAtTheOriginZeroWhereTheSiteDriftsTo56e17() {
        // `tick_drift_zero_label.svg`: `gx += step` over [-1, 1] at 0.2 never
        // lands on zero. `first + i * step` does.
        val chart = figure("x: -1..1\ny: -1..1\nx")
        assertEquals("0", chart.xLabels[5])
        assertEquals("0", chart.yLabels[5])
        // And `tick_drift_extra_tick.svg`, where the drift is 1.4e-16 instead.
        assertEquals("0", figure("x: -0.9..0.3\ny: -0.9..0.3\nx").xLabels[9])
    }

    @Test fun axisCorrectionKeepsTheTickThatLandsExactlyOnTheMaximum() {
        // The other half of computing by index: `0.0001 + 8 * 0.0001` is
        // 9.000000000000001e-4, a hair over the range's own maximum, and
        // dropping the last tick of an axis because of one ULP is a visible
        // defect. The site drops it (`tiny_range.svg` has eight ticks per axis).
        val chart = figure("x: 0.0001..0.0009\ny: 0.0001..0.0009\nx")
        assertEquals(9, chart.xLabels.size)
        assertEquals("9.0e-4", chart.xLabels[8])
    }

    // MARK: - §5 The 22 recorded figures

    /**
     * The figures whose recorded shape is one of the six corrected behaviours.
     *
     * Each entry lists only what differs from the vector; everything unlisted is
     * still asserted against the site's own numbers.
     */
    private class FigureFix(
        val polylines: Int? = null,
        val first: String? = null,
        val last: String? = null,
        val lines: Int? = null,
        val texts: Int? = null,
        val xLabels: List<String>? = null,
        val yLabels: List<String>? = null,
        @Suppress("unused") val why: String = "",
    )

    private val minusOneToOne =
        listOf("-1", "-0.80", "-0.60", "-0.40", "-0.20", "0", "0.20", "0.40", "0.60", "0.80", "1")
    private val minusNineToThree = listOf(
        "-0.90", "-0.80", "-0.70", "-0.60", "-0.50", "-0.40", "-0.30", "-0.20", "-0.10", "0",
        "0.10", "0.20", "0.30",
    )
    private val minusFiveToMinusThree =
        listOf("-5", "-4.80", "-4.60", "-4.40", "-4.20", "-4", "-3.80", "-3.60", "-3.40", "-3.20", "-3")
    private val tinyRangeLabels = listOf(
        "1.0e-4", "2.0e-4", "3.0e-4", "4.0e-4", "5.0e-4", "6.0e-4", "7.0e-4", "8.0e-4", "9.0e-4",
    )

    private val correctedFigures: Map<String, FigureFix> = mapOf(
        // floor(x) draws (correction 1).
        "broken_floor_no_curve" to FigureFix(
            polylines = 1, first = "248.00,360.00", last = "377.48,40.00", why = "floor is bound",
        ),
        // x>0 draws (correction 2).
        "boolean_no_curve" to FigureFix(
            polylines = 1, first = "40.00,200.00", last = "560.00,120.00",
            why = "a comparison is a number",
        ),
        // 5/2 is 2.5, and the origin's label is "0" and not "-5.6e-17".
        "int_division_trunc" to FigureFix(
            first = "40.00,200.00", last = "560.00,200.00", xLabels = minusOneToOne,
            why = "no integer division; no tick drift",
        ),
        "constant_three" to FigureFix(xLabels = minusOneToOne, why = "no tick drift"),
        "tick_drift_zero_label" to FigureFix(
            xLabels = minusOneToOne, yLabels = minusOneToOne, why = "no tick drift",
        ),
        "tick_drift_extra_tick" to FigureFix(
            xLabels = minusNineToThree, yLabels = minusNineToThree, why = "no tick drift",
        ),
        // The truncated label, and the tick at the maximum the site's
        // accumulation overshot: eleven ticks per axis rather than ten.
        "tick_label_truncation" to FigureFix(
            lines = 22, texts = 22, xLabels = minusFiveToMinusThree, yLabels = minusFiveToMinusThree,
            why = "labels are rounded, and the last tick is kept",
        ),
        "no_zero_on_either_axis" to FigureFix(
            lines = 20, texts = 20,
            xLabels = listOf("1", "1.20", "1.40", "1.60", "1.80", "2", "2.20", "2.40", "2.60", "2.80", "3"),
            why = "labels are rounded, and the last tick is kept",
        ),
        "tiny_range" to FigureFix(
            lines = 18, texts = 18, xLabels = tinyRangeLabels, yLabels = tinyRangeLabels,
            why = "the tick on the maximum is kept",
        ),
    )

    @Test fun thirteenOfTheTwentyTwoRecordedFiguresAreDrawnExactlyAsTheSiteDoes() {
        val recorded = rows("svg")
        assertEquals(22, recorded.size)
        var same = 0
        for (row in recorded) if (!correctedFigures.containsKey(row["name"].string())) same++
        assertEquals(13, same)
    }

    /**
     * One recorded figure, rebuilt from the range the generator wrote and
     * compared against every number it recorded.
     *
     * The range is rebuilt from the *literal* in the JSON rather than from a
     * re-formatted double, so `0.7999999999999998` reaches the parser as the
     * generator spelt it.
     */
    private fun assertFigure(name: String) {
        val row = rows("svg").first { it["name"].string() == name }
        val source = "x: ${row["xMin"].raw()}..${row["xMax"].raw()}\n" +
            "y: ${row["yMin"].raw()}..${row["yMax"].raw()}\n${row["expr"].string()}"
        val got = facts(Plot.plotSVG(source))
        val fix = correctedFigures[name] ?: FigureFix()

        // The spacing is `nice_step`, ported verbatim: never corrected.
        assertEquals(
            "$name x spacing",
            bits(row["xStep"].number()),
            bits(Plot.niceStep(row["xMax"].number() - row["xMin"].number())),
        )
        assertEquals(
            "$name y spacing",
            bits(row["yStep"].number()),
            bits(Plot.niceStep(row["yMax"].number() - row["yMin"].number())),
        )

        assertEquals("$name grid + axis lines", fix.lines ?: row["lineCount"].int(), got.lines)
        assertEquals("$name tick labels", fix.texts ?: row["textCount"].int(), got.texts)
        assertEquals("$name unbroken runs", fix.polylines ?: row["polylineCount"].int(), got.polylines)
        assertEquals("$name first plotted point", fix.first ?: row["firstPoint"].stringOrNull(), got.first)
        assertEquals("$name last plotted point", fix.last ?: row["lastPoint"].stringOrNull(), got.last)
        assertEquals("$name x tick labels", fix.xLabels ?: row["xTickLabels"].strings(), got.xLabels)
        assertEquals("$name y tick labels", fix.yLabels ?: row["yTickLabels"].strings(), got.yLabels)
    }

