    @Test fun breaksACurveWhereItLeavesTheWindowAndNowhereElse() {
        // tan(x) over [-10, 10] is seven branches; 1/x over [-5, 5] is two; a
        // single plottable sample is still a polyline of one point.
        assertEquals(7, figure("x: -10..10\ny: -2..2\ntan(x)").polylines)
        assertEquals(2, figure("x: -5..5\ny: -5..5\n1/x").polylines)
        assertEquals("300.00,200.00", figure("x: -10..10\ny: -0.005..0.005\nx").first)
    }

    @Test fun samplesWithTheFormulaTheSiteUsesNotTheCheaperOne() {
        // `xMin + (i / samples) * span`, never `xMin + i * dx`: the two differ
        // in the last bits for 221 of the 1001 default samples, and the
        // difference reaches the output.
        val chart = figure("x: -6.3..0.7999999999999998\ny: -3.3..3.1\nx")
        assertEquals("259.96,359.83", chart.first)
        assertEquals("560.00,155.00", chart.last)
    }

    // MARK: - §6 The fence

    @Test fun readsDirectivesInAnyOrderAndIgnoresBlanksAndComments() {
        val spec = Plot.parsePlot(
            listOf("# a comment", "", "sin(x)", "title: A title", "x: -1..1", "y: -2..2", "")
                .joinToString("\n"),
        )
        assertEquals("A title", spec.title)
        assertEquals(-1.0, spec.xMin, 0.0)
        assertEquals(1.0, spec.xMax, 0.0)
        assertEquals(-2.0, spec.yMin!!, 0.0)
        assertEquals(1, spec.series.size)
    }

    @Test fun treatsAnUnknownKeyLineAsALabelledSeriesNotAsAnError() {
        // `f: x` still plots. This is why the directive scan checks the key
        // against the known list before it claims the line, and why the series
        // parser then reads the key as a label.
        val spec = Plot.parsePlot("f: x")
        assertEquals(1, spec.series.size)
        assertEquals("f", spec.series[0].label)
        assertEquals("x", spec.series[0].source)
        assertTrue(Plot.plotSVG("f: sin(x)").contains("<polyline"))
    }

    @Test fun defaultsToMinusTenToTenAutoSixHundredByFourHundredAndAThousandSamples() {
        val spec = Plot.parsePlot("sin(x)")
        assertEquals(-10.0, spec.xMin, 0.0)
        assertEquals(10.0, spec.xMax, 0.0)
        assertNull(spec.yMin)
        assertEquals(600, spec.width)
        assertEquals(400, spec.height)
        assertEquals(1000, spec.samples)
        assertEquals(Plot.Legend.AUTO, spec.legend)
        assertTrue(spec.grid)
        assertTrue(spec.axes)
    }

    @Test fun clampsWidthHeightAndSamples() {
        val small = Plot.parsePlot("width: 10\nheight: 10\nsamples: 1\nx")
        assertEquals(160, small.width)
        assertEquals(120, small.height)
        assertEquals(50, small.samples)
        val large = Plot.parsePlot("width: 9000\nheight: 9000\nsamples: 90000\nx")
        assertEquals(2000, large.width)
        assertEquals(2000, large.height)
        assertEquals(5000, large.samples)
    }

    @Test fun takesAConstantExpressionAtEitherEndOfARange() {
        val spec = Plot.parsePlot("x: -pi..2*pi\nsin(x)")
        assertEquals(-Math.PI, spec.xMin, 0.0)
        assertEquals(2 * Math.PI, spec.xMax, 0.0)
    }

    @Test fun rejectsARangeThatDoesNotIncrease() {
        assertMessage("x range must be increasing") { Plot.parsePlot("x: 1..1\nx") }
        assertMessage("y range must be increasing") { Plot.parsePlot("y: 5..-5\nx") }
        assertThrowsPlotError("x: nonsense") { Plot.parsePlot("x: nonsense\nx") }
    }

    @Test fun splitsALabelOffTheFirstTopLevelBareEquals() {
        assertEquals("envelope", Plot.parsePlot("envelope = exp(-abs(x)/5)").series[0].label)
        assertEquals("exp(-abs(x)/5)", Plot.parsePlot("envelope = exp(-abs(x)/5)").series[0].source)
        // The FIRST one, so what follows still has to be an expression: there is
        // no assignment in the language for a second `=` to be part of.
        assertThrowsPlotError("a = b = x") { Plot.parsePlot("a = b = x") }
        // …and never off a comparison operator.
        for (source in listOf("x == 1", "x <= 1", "x >= 1", "x != 1")) {
            assertEquals(source, null, Plot.parsePlot(source).series[0].label)
        }
    }

    @Test fun readsAPointsSeriesAndAParametricSeries() {
        val points = Plot.parsePlot("measured = points: 0,0 1,2 2,1").series[0]
        assertEquals(Plot.SeriesKind.POINTS, points.kind)
        assertEquals("measured", points.label)
        assertEquals(
            listOf(Plot.Point(0.0, 0.0), Plot.Point(1.0, 2.0), Plot.Point(2.0, 1.0)),
            points.points,
        )

        val parametric = Plot.parsePlot("circle = (cos(t), sin(t)) for t in 0..2*pi").series[0]
        assertEquals(Plot.SeriesKind.PARAMETRIC, parametric.kind)
        assertEquals("t", parametric.parameter)
        assertEquals(0.0, parametric.tMin, 0.0)
        assertEquals(2 * Math.PI, parametric.tMax, 0.0)
        // The parametric variable is the only free name inside it: `x` is not.
        assertMessage("unknown name 'x'") { Plot.parsePlot("(x, sin(t)) for t in 0..1") }
    }

    @Test fun doesNotMistakeAParenthesisedExpressionForAParametricOne() {
        assertEquals(Plot.SeriesKind.FUNCTION, Plot.parsePlot("(x+1)*2").series[0].kind)
        // A pair with no `for` is not a parametric series, so it is read as an
        // expression — and a tuple is not one of those.
        assertThrowsPlotError("(x, x)") { Plot.parsePlot("(x, x)") }
    }

    @Test fun fitsYAutoToTheFiniteSamplesWithFivePercentOfPadding() {
        // sin over a whole period reaches ±1 (to the last sample), so the window
        // is 1.05 either way.
        assertTrue(Plot.plotSVG("x: -10..10\nsin(x)").contains(">1</text>"))
        // A series with nothing finite in it falls back to -1..1.
        assertTrue(Plot.plotSVG("x: -10..10\nsqrt(-1)+x*0").contains(">1</text>"))
        // A flat series has no span to take 5 % of: it is padded by 5 % of itself.
        assertEquals(1, Plot.parsePlot("x: -1..1\n3").series.size)
        assertTrue(Plot.plotSVG("x: -1..1\n3").contains("<polyline"))
    }

    @Test fun showsTheLegendWhenThereAreTwoSeriesOrOneThatIsLabelled() {
        val legendGroup = "font-size=\"11\" font-family=\"sans-serif\""
        assertFalse(Plot.plotSVG("x: -1..1\nsin(x)").contains(legendGroup))
        assertTrue(Plot.plotSVG("x: -1..1\nsin(x)\ncos(x)").contains(legendGroup))
        assertTrue(Plot.plotSVG("x: -1..1\nwave = sin(x)").contains(">wave</text>"))
        assertFalse(Plot.plotSVG("x: -1..1\nlegend: off\nsin(x)\ncos(x)").contains(legendGroup))
        // An unlabelled series' legend text is its own source.
        assertTrue(Plot.plotSVG("x: -1..1\nlegend: on\nsin(x)").contains(">sin(x)</text>"))
    }

    @Test fun turnsTheGridAndTheAxesOff() {
        val bare = Plot.plotSVG("x: -1..1\ngrid: off\naxes: off\nx")
        assertFalse(bare.contains("<line"))
        assertFalse(bare.contains("<text x="))
        assertFalse(bare.contains("<rect"))
        assertTrue(bare.contains("<polyline"))
        assertMessage("grid must be 'on' or 'off'") { Plot.parsePlot("grid: sometimes\nx") }
    }

    @Test fun givesEachSeriesTheNextColourPurpleFirst() {
        val svg = Plot.plotSVG("x: -1..1\nx\nx+0.1\nx+0.2")
        assertTrue(svg.contains("stroke=\"#673AB7\""))
        assertTrue(svg.contains("stroke=\"#E5390F\""))
        assertTrue(svg.contains("stroke=\"#0F9D58\""))
    }

    // MARK: - §7 The container, and what must never be in it

    private val sampleSvg = Plot.plotSVG("x: -10..10\ntitle: T\nsin(x)")

    @Test fun isADivPlotAroundOneSvgWithAViewBox() {
        val block = Plot.renderPlot("x: -10..10\nsin(x)")
        assertTrue(block.startsWith("<div class=\"plot\"><svg "))
        assertTrue(block.endsWith("</svg></div>"))
        // Without a viewBox, `max-width: 100%; height: auto` shrinks the box and
        // clips the drawing instead of scaling it.
        assertTrue(block.contains("viewBox=\"0 0 600 400\""))
        assertTrue(block.contains("width=\"600\" height=\"400\" role=\"img\""))
    }

    @Test fun carriesNoIdAtAll() {
        // SPEC §1.5: a duplicated id is how one figure ends up wearing another's
        // clip path once a document holds two plots. An `<svg role="img">` is
        // named by its own `<title>`, with no `aria-labelledby` to point at, so
        // there is nothing to number.
        val two = Plot.renderPlot("sin(x)") + Plot.renderPlot("cos(x)")
        assertFalse(two.contains(" id="))
        assertFalse(two.contains("aria-labelledby"))
        assertTrue(sampleSvg.contains("<title>T</title>"))
        assertTrue(Plot.plotSVG("sin(x)").contains("<title>Plot of sin(x)</title>"))
    }

    @Test fun paintsWithCurrentColorAndBakesOnlyTheSeriesColours() {
        // `renderBlock` is theme-blind in all four repos, so one SVG has to be
        // right in a light preview, a dark preview, print, an exported page and
        // a saved file. A baked grey is a light-mode assumption.
        assertTrue(sampleSvg.contains("stroke=\"currentColor\""))
        assertTrue(sampleSvg.contains("fill=\"currentColor\""))
        for (grey in listOf("#e0e0e0", "#999", "#666", "#ccc")) {
            assertFalse(grey, sampleSvg.contains(grey))
        }
        assertFalse(sampleSvg.contains("background:white"))
        assertTrue(sampleSvg.contains("stroke=\"#673AB7\""))
    }

    @Test fun embedsNoStyleScriptForeignObjectOrFont() {
        // An SVG `<style>` inside an HTML document is document-scoped and leaks.
        for (forbidden in listOf("<style", "<script", "<foreignObject", "@font-face", "<image")) {
            assertFalse(forbidden, sampleSvg.contains(forbidden))
        }
    }

    @Test fun xmlEscapesEveryAuthorStringWithTheFiveXmlEntitiesAndNoOther() {
        // The EPUB body is XHTML, which is XML: one raw `&` makes the whole
        // content document unparseable and the book unopenable. And a named
        // entity like `&nbsp;` is undefined in XML, so escaping may only ever
        // produce the five.
        val hostile = Plot.plotSVG(
            listOf("title: A & B <c> \"d\"", "xlabel: <x>", "ylabel: &y;", "p & q = x").joinToString("\n"),
        )
        assertTrue(hostile.contains("<title>A &amp; B &lt;c&gt; &quot;d&quot;</title>"))
        assertTrue(hostile.contains(">&lt;x&gt;</text>"))
        assertTrue(hostile.contains(">&amp;y;</text>"))
        assertTrue(hostile.contains(">p &amp; q</text>"))
        assertFalse(hostile.contains("&nbsp;"))
        for (entity in Regex("&[a-z]+;").findAll(hostile).map { it.value }) {
            assertTrue(entity, entity in listOf("&amp;", "&lt;", "&gt;", "&quot;", "&apos;"))
        }
    }

    @Test fun emitsTheContainerEvenForAnEmptyBlockAndABrokenOne() {
        // If it is ever omitted the SVG-export ordinals desynchronise and every
        // later diagram exports the wrong figure.
        assertEquals("<div class=\"plot\"></div>", Plot.renderPlot(""))
        assertEquals("<div class=\"plot\"></div>", Plot.renderPlot("# only a comment"))
        val broken = Plot.renderPlot("sinc(x)")
        assertTrue(broken.startsWith("<div class=\"plot\"><pre>"))
        assertTrue(broken.contains("plot: unknown function 'sinc'"))
        assertTrue(broken.contains("sinc(x)")) // the source always stays visible
        assertTrue(Plot.renderPlot("x: 1..1\nx").contains("plot: x range must be increasing"))
    }

    @Test fun escapesTheSourceItFallsBackTo() {
        assertTrue(Plot.renderPlot("<b>&</b>").contains("&lt;b&gt;&amp;&lt;/b&gt;"))
    }

    @Test fun neverReturnsAnythingButAContainerWhateverItIsHanded() {
        // The renderer runs inside the Markdown renderer, which has no other
        // failure mode: whatever a fence contains, the answer is a `div.plot`
        // with either a drawing or the source in it, and every coordinate in
        // that drawing is a real number. A stack overflow on 200 nested
        // parentheses is caught by the depth budget here — on this platform it
        // would be a crash, not an exception — and the author's own text still
        // comes back.
        val hostile = listOf(
            "", "   ", "#", "x: 0..0\nx", "y: 1..0\nx", "width: -5\nheight: abc\nx",
            "points:", "points: 1", "label =", "= x", "(cos(t), sin(t)) for t in 0..0",
            "(cos(t), sin(t)) for u in 0..1", "x: 1e308..-1e308\nx", "x: -1e308..1e308\nx",
            "x: 0.0000001..0.0000002\nx", "axes: off\ngrid: off\nx", "ln(x)", "x^x",
            "sqrt(-x)", "0/0", "x*0/0", "(".repeat(200) + "x", "title: " + "A".repeat(500) + "\nx",
            "y: -1..1\n" + "sin(x)\n".repeat(12),
        )
        val attribute = Regex(" (?:x|y|x1|y1|x2|y2|width|height|cx|cy)=\"([^\"]*)\"")
        for (source in hostile) {
            val html = Plot.renderPlot(source)
            assertTrue(source, html.startsWith("<div class=\"plot\">"))
            assertTrue(source, html.endsWith("</div>"))
            for (match in attribute.findAll(html)) {
                val text = match.groupValues[1]
                assertTrue("$source → $text", text.toDoubleOrNull()?.isFinite() == true)
            }
            for (run in Regex("points=\"([^\"]*)\"").findAll(html)) {
                for (pair in run.groupValues[1].split(" ")) {
                    val halves = pair.split(",")
                    assertEquals(pair, 2, halves.size)
                    assertTrue(pair, halves[0].toDoubleOrNull()?.isFinite() == true)
                    assertTrue(pair, halves[1].toDoubleOrNull()?.isFinite() == true)
                }
            }
        }
    }

    @Test fun survivesAFigureSqueezedToTheSmallestCanvas() {
        // Title, both axis labels and a legend on a 160 × 120 canvas would
        // compute a negative plot area without `fitMargins`.
        val tiny = Plot.plotSVG(
            listOf("width: 160", "height: 120", "title: T", "xlabel: x", "ylabel: y", "legend: on", "a = x")
                .joinToString("\n"),
        )
        assertTrue(tiny.contains("viewBox=\"0 0 160 120\""))
        assertFalse(tiny.contains("NaN"))
        // The plot area is still a real rectangle, inside the canvas.
        val rect = Regex("<rect x=\"([\\d.]+)\" y=\"([\\d.]+)\" width=\"([\\d.]+)\" height=\"([\\d.]+)\"")
            .find(tiny)
        assertNotNull(rect)
        val (x, y, w, h) = rect!!.groupValues.drop(1).map { it.toDouble() }
        assertTrue(w >= 40)
        assertTrue(h >= 40)
        assertTrue(x + w <= 160)
        assertTrue(y + h <= 120)
    }

    // MARK: - §8 The renderer, the settings and every export path

    private val fence = listOf("```plot", "x: -10..10", "sin(x)", "```").joinToString("\n")

    @Test fun dispatchesTheFenceToAPlotContainer() {
        val html = MarkdownHtml.document(fence, "t", dark = false)
        assertTrue(html.contains("<div class=\"plot\"><svg"))
        // The class is exactly `plot`, which keeps all five engine probes false:
        // a plot-only document loads no engine at all, and there is no `needs`
        // flag to add.
        for (engine in listOf("katex.min.js", "mermaid.min.js", "viz-global.js", "highlight.min.js")) {
            assertFalse(engine, html.contains(engine))
        }
        assertFalse(html.contains("class=\"language-"))
    }

    @Test fun isStyledByBothStylesheetsTheSharedOneAndTheEpubsOwn() {
        // Two sheets, because the EPUB carries a hand-written stylesheet of its
        // own (`Epub.EPUB_CSS`) that the shared one never reaches — the one
        // edit site the two Apple ports do not have.
        val exported = MarkdownHtml.document(fence, "t", dark = false)
        assertTrue(exported.contains(".mermaid, .plantuml, .graphviz, .plot, .md-mathd {"))
        assertTrue(
            exported.contains(
                ".mermaid svg, .plantuml svg, .graphviz svg, .plot svg { max-width: 100%; height: auto; }",
            ),
        )
        assertTrue(me.nettrash.md.book.EPUB_CSS.contains(".plot svg { max-width: 100%; height: auto; }"))
    }

    @Test fun offersTheFigureToTheSvgExport() {
        val document = listOf(fence, "", "```dot", "digraph {}", "```").joinToString("\n")
        val found = DiagramSvg.diagrams(document)
        assertEquals(listOf(DiagramSvg.Kind.PLOT, DiagramSvg.Kind.GRAPHVIZ), found.map { it.kind })
        assertEquals("Plot", found[0].typeName)
        assertEquals("Plot: x: -10..10", found[0].menuTitle)
        // A quoted plot keeps its place, because the renderer recurses into
        // quotes.
        assertEquals(
            listOf(DiagramSvg.Kind.PLOT),
            DiagramSvg.diagrams(listOf("> ```plot", "> sin(x)", "> ```").joinToString("\n")).map { it.kind },
        )
        // The DOM query that pairs with this walk lives in `ui/Exporter`
        // (`pre.mermaid, div.plantuml, div.graphviz, div.plot`) and is
        // device-only, so it is not reachable from a JVM test — the reference
        // suite asserts its own `DIAGRAM_SELECTOR` here instead. The two must
        // keep agreeing about what a diagram is, or every later figure exports
        // as the wrong one.
    }

    @Test fun savesAsAStandaloneSvgWithoutAFixUp() {
        // The root already carries `xmlns`, `width` and `height`, so the only
        // thing the writer adds is the XML prolog.
        val file = DiagramSvg.standaloneDocument(Plot.plotSVG("sin(x)"))
        assertTrue(file.startsWith("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<svg xmlns="))
        assertTrue(file.contains("width=\"600\" height=\"400\""))
    }

    @Test fun keepsTheSourceInTheLatexExportUnderAComment() {
        val tex = LaTeXExport.document(fence)
        assertTrue(tex.contains("% plot diagram source"))
        assertTrue(tex.contains("\\begin{verbatim}"))
        assertTrue(tex.contains("sin(x)"))
    }

    @Test fun passesTheEpubsXhtmlFixerUntouchedAndAsksForPropertiesSvg() {
        // The fixer has never seen an SVG before: `toXhtml` self-closes void
        // elements with an *unanchored* alternation, so `<line>` and
        // `<polyline>` are exactly the shapes to check before trusting it.
        val body = documentBody(MarkdownHtml.document(fence, "t", dark = false))
        assertTrue(body.contains("<line "))
        assertTrue(body.contains("<polyline "))
        assertEquals(body, toXhtml(body))

        // EPUB 3 requires the reserved property on any content document holding
        // an `<svg>`; without it EPUBCheck reports OPF-014 and the book is
        // invalid.
        val withSvg = EpubUnit("content.xhtml", "t", toXhtml(body))
        val withoutSvg = EpubUnit("content.xhtml", "t", "<p>plain</p>")
        assertTrue(
            contentOpf(EpubBook("t", withSvg, emptyList(), emptyList(), emptyList()), "i", "m").contains(
                "<item id=\"content\" href=\"content.xhtml\" " +
                    "media-type=\"application/xhtml+xml\" properties=\"svg\"/>",
            ),
        )
        // …and a document without one is still emitted bare.
        assertTrue(
            contentOpf(EpubBook("t", withoutSvg, emptyList(), emptyList(), emptyList()), "i", "m").contains(
                "<item id=\"content\" href=\"content.xhtml\" media-type=\"application/xhtml+xml\"/>",
            ),
        )
    }

    @Test fun keepsTheLiteralSvgTagOutOfTheStylesheetTheOpfHeuristicSearchesFor() {
        // `contentOpf` decides `properties="svg"` by searching a content
        // document for the four characters `<svg`, which is only sound while
        // nothing *but* a figure puts them there. The stylesheet is
        // interpolated into every document's <style>, so a `<svg>` written in
        // one of its comments would be in every document this renderer emits —
        // harmless only because the EPUB body excludes the head, which is one
        // refactor of `documentBody` away from being a silent false positive on
        // every book. So the string is not allowed in the sheet at all.
        val plain = MarkdownHtml.document("just prose\n", "t", dark = false)
        assertFalse("a plot-free document must not contain the OPF marker", plain.contains("<svg"))
        for (dark in listOf(false, true)) {
            for (export in listOf(false, true)) {
                assertFalse(
                    "stylesheet dark=$dark export=$export",
                    MarkdownHtml.document("x\n", "t", dark = dark, export = export).contains("<svg"),
                )
            }
        }
    }

    @Test fun theEpubContentDocumentHoldingAPlotIsWellFormedXml() {
        // The whole reason every author string is escaped: an EPUB content
        // document is XHTML, which is XML, and one raw `&` or `<` makes the
        // book unopenable rather than merely ugly. A hostile title, both axis
        // labels and a legend label go through the same parser a reader would
        // use — with no network access, so a DTD reference could not be
        // resolved even if one were emitted.
        val fence = listOf(
            "```plot",
            "x: -10..10",
            "title: A & B <c> \"d\"",
            "xlabel: <x>",
            "ylabel: &y;",
            "p & q = sin(x)",
            "```",
        ).joinToString("\n")
        val body = toXhtml(documentBody(MarkdownHtml.document(fence, "t", dark = false)))
        val document = javax.xml.parsers.DocumentBuilderFactory.newInstance()
            .newDocumentBuilder()
            .parse(org.xml.sax.InputSource(java.io.StringReader(xhtmlDocument("t", body))))
        assertEquals(1, document.getElementsByTagName("svg").length)
        assertEquals("A & B <c> \"d\"", document.getElementsByTagName("title").item(1).textContent)
    }

    // MARK: - §8b The render cache

    /**
     * Why this exists at all: `plot` is the only rich block drawn *in the
     * renderer*, synchronously, so the live preview pays for every figure in a
     * document on every keystroke — the 0.35 s debounce delays the WebView
     * reload, not the render. Measured in a release build: 4.87 ms for one
     * default figure, 36 ms for an eight-series one, 187 ms for a document of
     * four of those and 289 ms for ten `samples: 5000` figures. The per-fence
     * caps bound a fence, not a document.
     *
     * The fix is a memo, because [Plot.renderPlot] is a pure function of its
     * fence text: while an author types a sentence, every plot in the document
     * is a hit. These tests are the whole assurance that it is really a memo —
     * a cache is invisible in the output by construction, so `renderCount`
     * (drawings, not calls) is what makes a hit observable.
     */
    @Test fun rendersEachDistinctFenceOnceAndServesTheRepeatFromTheCache() {
        Plot.resetRenderCacheForTest()
        val source = "x: -10..10\nsin(x)"

        val first = Plot.renderPlot(source)
        assertEquals(1L, Plot.renderCacheStateForTest().second)

        // Twenty more calls with the identical text — the preview's keystroke
        // loop, in miniature. One drawing, twenty identical answers.
        repeat(20) { assertEquals(first, Plot.renderPlot(source)) }
        assertEquals(1L, Plot.renderCacheStateForTest().second)
        assertEquals(1, Plot.renderCacheStateForTest().first)

        // A different fence is a different key: the memo is on the text, not on
        // "the last thing rendered".
        Plot.renderPlot("x: -10..10\ncos(x)")
        assertEquals(2L, Plot.renderCacheStateForTest().second)
        assertEquals(first, Plot.renderPlot(source))
        assertEquals(2L, Plot.renderCacheStateForTest().second)
    }

    @Test fun cachesFailuresToo() {
        // A half-typed fence is a parse failure, and that is the state a fence
        // spends most of its life in while it is being written. Re-running the
        // parser on every keystroke to re-learn "expected ')'" is exactly the
        // cost this is here to remove, so the failure path is memoised on the
        // same terms as the success path.
        Plot.resetRenderCacheForTest()
        val broken = "x: -10..10\nsin(x"

        val first = Plot.renderPlot(broken)
        assertTrue(first.contains("plot: expected ')'"))
        assertEquals(1L, Plot.renderCacheStateForTest().second)
        repeat(10) { assertEquals(first, Plot.renderPlot(broken)) }
        assertEquals(1L, Plot.renderCacheStateForTest().second)

        // And the empty fence, which is not an error and draws nothing.
        Plot.renderPlot("")
        Plot.renderPlot("")
        assertEquals(2L, Plot.renderCacheStateForTest().second)
    }

    @Test fun evictsTheLeastRecentlyUsedFenceAtThirtyTwoEntries() {
        Plot.resetRenderCacheForTest()
        // 32 is what md.vscode's preview client already uses for its diagram
        // cache; the four ports bound the same thing the same way. Bounded at
        // all because an editing session types thousands of distinct
        // intermediate fences and never asks for one of them twice.
        val fences = (0 until 32).map { "x: -10..10\nsin(x)+$it" }
        for (source in fences) Plot.renderPlot(source)
        var state = Plot.renderCacheStateForTest()
        assertEquals(32, state.first)
        assertEquals(32L, state.second)

        // Touch the oldest so it is no longer the eldest — a read counts as a
        // use, which is what keeps the figures a document is *showing* resident
        // while the junk between keystrokes ages out.
        Plot.renderPlot(fences[0])
        assertEquals(32L, Plot.renderCacheStateForTest().second)

        // The thirty-third entry evicts fences[1], not fences[0].
        Plot.renderPlot("x: -10..10\ncos(x)")
        state = Plot.renderCacheStateForTest()
        assertEquals(32, state.first)
        assertEquals(33L, state.second)
        assertTrue(state.third.contains(fences[0]))
        assertFalse(state.third.contains(fences[1]))

        // …and asking for the evicted one draws it again, which is the proof
        // that it really left rather than merely stopped being counted.
        Plot.renderPlot(fences[1])
        assertEquals(34L, Plot.renderCacheStateForTest().second)
        assertEquals(32, Plot.renderCacheStateForTest().first)
    }

    @Test fun theCacheNeverChangesWhatAFenceRendersTo() {
        // The one thing a memo must not do. Every recorded figure, drawn cold
        // and then drawn again through a full cache, byte for byte.
        val sources = rows("svg").map { row ->
            // The literal the generator wrote, as `assertFigure` uses it — a
            // re-formatted double would not always re-parse.
            "x: ${row["xMin"].raw()}..${row["xMax"].raw()}\n" +
                "y: ${row["yMin"].raw()}..${row["yMax"].raw()}\n${row["expr"].string()}"
        }
        Plot.resetRenderCacheForTest()
        val cold = sources.map { Plot.renderPlot(it) }
        // 22 recorded figures against a 32-entry cache: run them twice more so
        // the second pass is served entirely from it.
        repeat(2) {
            for ((index, source) in sources.withIndex()) {
                assertEquals(cold[index], Plot.renderPlot(source))
            }
        }
        assertEquals(sources.size.toLong(), Plot.renderCacheStateForTest().second)
        // Uncached, from the same input, is the same bytes as cached.
        Plot.resetRenderCacheForTest()
        for ((index, source) in sources.withIndex()) {
            assertEquals(cold[index], Plot.renderPlot(source))
        }
    }

    // MARK: - §9 The figure itself, byte for byte

    @Test fun drawsTheSpecsOwnExampleAsRecorded() {
        // The whole SVG of one document, pinned — and pinned against
        // **md.vscode's own golden file**, byte for byte, which is the entire
        // cross-port parity claim: same fence, same 31,647 bytes, in TypeScript
        // and in Kotlin. Not a specification and not documentation: a tripwire,
        // so that a change to a coordinate, an opacity or an attribute order
        // shows up as a diff to read rather than as nothing at all.
        val source = listOf(
            "x: -10..10",
            "y: -2..2",
            "title: Damped oscillation",
            "xlabel: x",
            "ylabel: amplitude",
            "envelope = exp(-abs(x)/5)",
            "sin(x) * exp(-abs(x)/5)",
        ).joinToString("\n")
        val golden = checkNotNull(
            javaClass.classLoader?.getResourceAsStream("plot-damped-oscillation.svg"),
        ) { "missing plot-damped-oscillation.svg" }.readBytes().toString(Charsets.UTF_8)
        val got = Plot.renderPlot(source) + "\n"
        if (got != golden) {
            // Name the first difference rather than dumping 31 KB twice.
            var index = 0
            while (index < got.length && index < golden.length && got[index] == golden[index]) index++
            val from = maxOf(0, index - 60)
            throw AssertionError(
                "golden differs at byte $index (ours ${got.length} bytes, golden ${golden.length})\n" +
                    "ours:   …${got.substring(from, minOf(got.length, index + 60))}\n" +
                    "golden: …${golden.substring(from, minOf(golden.length, index + 60))}",
            )
        }
        assertEquals(31647, golden.toByteArray(Charsets.UTF_8).size)
    }

    // MARK: - §10 Resource limits and degenerate magnitudes

    // Each of these was found by an adversarial pass against the reference, and
    // each is a way it could have taught the same defect to this port. A stack
    // overflow is an exception there and a crash here, so the guards matter more
    // in this file than in that one.

    @Test fun drawsASeriesWhoseValuesOverflowThePaddedRange() {
        // `high - low` overflows for a series straddling ~1e308, which made
        // every sy() NaN and emitted points="40.00,NaN …" — a curve that
        // vanished with nothing to say why.
        val out = Plot.renderPlot("x: -10..10\nx*1e307")
        assertFalse(out.contains("NaN"))
        assertTrue(out.contains("<polyline"))
    }

    @Test fun leavesAHugeButNarrowRangeExactlyAsAsked() {
        // The guard must fire on an overflowing *width*, not on a large bound:
        // [1.69e308, 1.71e308] is only 2e306 wide and is perfectly drawable.
        val out = Plot.renderPlot("x: -1..1\ny: 1.69e308..1.71e308\n1.7e308")
        assertFalse(out.contains("NaN"))
        assertTrue(out.contains("<polyline"))
    }

    @Test fun reportsDeepNestingAsAPlotLineNotAStackOverflow() {
        val source = "x: -1..1\n" + "(".repeat(5000) + "x" + ")".repeat(5000)
        assertTrue(Plot.renderPlot(source).contains("plot: expression nested too deeply"))
    }

    @Test fun reportsALongFlatChainTooWhichTheDepthGuardCannotSee() {
        // `x+x+x+…` parses at constant depth through the left-associative loop
        // and then overflows the stack in the evaluator, so depth alone is not
        // enough.
        val source = "x: -1..1\nx" + "+x".repeat(20000)
        assertTrue(Plot.renderPlot(source).contains("plot: expression too large"))
    }

    @Test fun capsTheSeriesCountTheOneInputWithNoClamp() {
        val source = "x: -1..1\n" + (1..1000).joinToString("\n") { "x*$it" }
        assertTrue(Plot.renderPlot(source).contains("plot: too many series"))
    }

    @Test fun drawsTheAxesADirectivesOnlyBlockDescribes() {
        // Not an empty block: the author wrote three lines. Returning an empty
        // container would swallow them, and the family rule is never a hole.
        val out = Plot.renderPlot("x: -10..10\ntitle: My chart\nylabel: y")
        assertTrue(out.contains("<svg"))
        assertTrue(out.contains("My chart"))
    }

    @Test fun stillDrawsNothingForAGenuinelyEmptyBlock() {
        assertEquals("<div class=\"plot\"></div>", Plot.renderPlot(""))
    }

    // MARK: - Assertion helpers

    private fun assertThrowsPlotError(what: String, body: () -> Unit) {
        try {
            body()
        } catch (error: Plot.PlotError) {
            assertNotNull(error.message)
            return
        }
        throw AssertionError("`$what` should have been a PlotError")
    }

    private fun assertMessage(fragment: String, body: () -> Unit) {
        try {
            body()
        } catch (error: Plot.PlotError) {
            assertTrue(
                "wanted a message containing \"$fragment\", got \"${error.message}\"",
                error.message.orEmpty().contains(fragment),
            )
            return
        }
        throw AssertionError("nothing was thrown, wanted \"$fragment\"")
    }

    // MARK: - Small text helpers, hand-written so a regex cannot drift

    private fun countOf(text: String, needle: String): Int {
        var count = 0
        var index = text.indexOf(needle)
        while (index >= 0) {
            count++
            index = text.indexOf(needle, index + needle.length)
        }
        return count
    }

    /** Every span between [opener] and the next [closer], in order. */
    private fun allGroups(text: String, opener: String, closer: String): List<String> {
        val out = ArrayList<String>()
        var index = text.indexOf(opener)
        while (index >= 0) {
            val start = index + opener.length
            val end = text.indexOf(closer, start)
            if (end < 0) break
            out.add(text.substring(start, end))
            index = text.indexOf(opener, end)
        }
        return out
    }
}

// MARK: - A JSON reader
//
// Thirty lines of recursive descent, because the unit-test classpath has JUnit
// and nothing else: `org.json` is Android's, and under `./gradlew test` every
// one of its methods throws "not mocked". A number keeps its source text as
// well as its value, so a range can be rebuilt from the literal the generator
// wrote rather than from a re-formatted double.

internal class JsonValue private constructor(
    private val kind: Int,
    private val text: String,
    private val fields: Map<String, JsonValue>?,
    private val items: List<JsonValue>?,
) {
    val isString: Boolean get() = kind == STRING

    fun string(): String {
        demand(kind == STRING, "string")
        return text
    }

    fun stringOrNull(): String? = if (kind == NULL) null else string()

    fun number(): Double {
        demand(kind == NUMBER, "number")
        return text.toDouble()
    }

    fun int(): Int = number().toInt()

    /** The literal the generator wrote, so a rebuilt range is bit-identical. */
    fun raw(): String {
        demand(kind == NUMBER, "number")
        return text
    }

    fun array(): List<JsonValue> {
        demand(kind == ARRAY, "array")
        return items!!
    }

    fun strings(): List<String> = array().map { it.string() }

    operator fun get(key: String): JsonValue {
        demand(kind == OBJECT, "object")
        return fields!![key] ?: throw AssertionError("no key '$key'")
    }

    override fun toString(): String = text

    private fun demand(condition: Boolean, wanted: String) {
        if (!condition) throw AssertionError("not a $wanted: $text")
    }

    internal companion object {
        const val OBJECT = 0
        const val ARRAY = 1
        const val STRING = 2
        const val NUMBER = 3
        const val LITERAL = 4
        const val NULL = 5

        fun obj(fields: Map<String, JsonValue>) = JsonValue(OBJECT, "", fields, null)
        fun arr(items: List<JsonValue>) = JsonValue(ARRAY, "", null, items)
        fun str(text: String) = JsonValue(STRING, text, null, null)
        fun num(text: String) = JsonValue(NUMBER, text, null, null)
        fun literal(text: String) =
            JsonValue(if (text == "null") NULL else LITERAL, text, null, null)
    }
}

internal object Json {

    fun parse(text: String): JsonValue {
        val reader = Reader(text)
        reader.skipSpace()
        val value = reader.value()
        reader.skipSpace()
        return value
    }

    private class Reader(private val text: String) {
        private var index = 0

        fun skipSpace() {
            while (index < text.length && text[index].code <= ' '.code) index++
        }

        fun value(): JsonValue {
            skipSpace()
            return when (text[index]) {
                '{' -> obj()
                '[' -> arr()
                '"' -> JsonValue.str(string())
                't', 'f', 'n' -> literal()
                else -> number()
            }
        }

        private fun obj(): JsonValue {
            index++ // '{'
            val fields = LinkedHashMap<String, JsonValue>()
            skipSpace()
            if (text[index] == '}') {
                index++
                return JsonValue.obj(fields)
            }
            while (true) {
                skipSpace()
                val key = string()
                skipSpace()
                index++ // ':'
                fields[key] = value()
                skipSpace()
                val c = text[index]
                index++
                if (c == '}') return JsonValue.obj(fields)
            }
        }

        private fun arr(): JsonValue {
            index++ // '['
            val items = ArrayList<JsonValue>()
            skipSpace()
            if (text[index] == ']') {
                index++
                return JsonValue.arr(items)
            }
            while (true) {
                items.add(value())
                skipSpace()
                val c = text[index]
                index++
                if (c == ']') return JsonValue.arr(items)
            }
        }

        private fun string(): String {
            index++ // '"'
            val out = StringBuilder()
            while (text[index] != '"') {
                val c = text[index]
                if (c == '\\') {
                    index++
                    when (val escape = text[index]) {
                        '"', '\\', '/' -> out.append(escape)
                        'b' -> out.append('\b')
                        'f' -> out.append('\u000C')
                        'n' -> out.append('\n')
                        'r' -> out.append('\r')
                        't' -> out.append('\t')
                        'u' -> {
                            out.append(text.substring(index + 1, index + 5).toInt(16).toChar())
                            index += 4
                        }
                        else -> throw AssertionError("bad escape \\$escape")
                    }
                } else {
                    out.append(c)
                }
                index++
            }
            index++ // '"'
            return out.toString()
        }

        private fun literal(): JsonValue {
            val start = index
            while (index < text.length && text[index] in 'a'..'z') index++
            return JsonValue.literal(text.substring(start, index))
        }

        private fun number(): JsonValue {
            val start = index
            while (index < text.length && (
                    text[index] in '0'..'9' || text[index] == '-' || text[index] == '+' ||
                        text[index] == '.' || text[index] == 'e' || text[index] == 'E'
                    )
            ) {
                index++
            }
            return JsonValue.num(text.substring(start, index))
        }
    }
}
